void sourceEvaluate(){set<int>kept;for(auto&r:matrixRoots)for(int i:r)kept.insert(i);vector<int>use(infos.size());for(int i:sourceNeeded){auto&o=infos[i];if(o.op!='p'){use[o.a]++;if(o.op!='k')use[o.b]++;}}for(int i:kept)use[i]++;V.resize(infos.size());Rat one;
 for(int i:sourceNeeded){cur.phase="source";cur.source=i;auto&o=infos[i];if(o.op=='p')V[i]=o.atom;else{Poly*p=makePoly(o.c,1,i);V[i]=p;Big scale;if(o.op=='m'){Rat expected=qmul(V[o.a]->c,V[o.b]->c);assert(fmpq_equal(expected.q,o.c.q));fmpz_one(scale.z);addMul(p,V[o.a],V[o.b],scale.z);}else if(o.op=='k'){assert(fmpq_equal(o.c.q,V[o.a]->c.q));fmpz_one(scale.z);addScaled(p,V[o.a],scale.z,o.shift);}else{Rat expected=qgcd(V[o.a]->c,V[o.b]->c);assert(fmpq_equal(expected.q,o.c.q));integerRatio(scale,V[o.a]->c,one,o.c);addScaled(p,V[o.a],scale.z);integerRatio(scale,V[o.b]->c,one,o.c);if(o.op=='s')fmpz_neg(scale.z,scale.z);addScaled(p,V[o.b],scale.z);}p->complete=true;if(!--use[o.a]&&!V[o.a]->input)destroy(V[o.a]);if(o.op!='k'&&!--use[o.b]&&!V[o.b]->input)destroy(V[o.b]);}assert(long(V[i]->a.size())<=o.upper);sourceDone++;clockcheck();}}
void normalizeKnownContent(Poly*p,const Rat&exact){Rat one;Big ratio,g;integerRatio(ratio,exact,one,p->c);assert(fmpz_sgn(ratio.z)>0);fmpz_zero(g.z);for(auto&[m,c]:p->a)fmpz_gcd(g.z,g.z,c->z);assert(fmpz_equal(g.z,ratio.z));for(auto&[m,c]:p->a){assert(fmpz_divisible(c->z,ratio.z));fmpz_divexact(c->z,c->z,ratio.z);}p->c=exact;}
string jsonEscape(const string&s){string out;for(char c:s){if(c=='"'||c=='\\')out+='\\';if(c=='\n')out+="\\n";else out+=c;}return out;}
template<class T>void writeLE(ostream&o,T x){using U=make_unsigned_t<T>;U v=static_cast<U>(x);for(size_t i=0;i<sizeof(T);i++)o.put(char((v>>(8*i))&255));}
void writeZ(ostream&o,const fmpz_t z,int limit){if(bits(z)>limit)throw runtime_error("checkpoint_integer_bitbound");char*s=fmpz_get_str(nullptr,16,z);string h=s;flint_free(s);bool neg=!h.empty()&&h[0]=='-';if(neg)h.erase(h.begin());if(h.size()%2)h='0'+h;uint16_t n=fmpz_is_zero(z)?0:h.size()/2;writeLE<uint16_t>(o,n);o.put(neg?1:0);for(int i=0;i<n;i++)o.put(char(stoul(h.substr(2*i,2),nullptr,16)));}
void checkpoint(const string&path,bool complete,const string&reason){cur.reason=reason;ostringstream h;h<<"{\"version\":\"K92SP001\",\"input_sha256\":\""<<inputHash<<"\",\"complete\":"<<(complete?"true":"false")<<",\"phase\":\""<<jsonEscape(cur.phase)<<"\",\"reason\":\""<<jsonEscape(reason)<<"\",\"source\":"<<cur.source<<",\"term\":"<<cur.term<<",\"row\":"<<cur.row<<",\"mask\":"<<cur.mask<<",\"column\":"<<cur.column<<",\"updates\":"<<updates<<",\"source_completed\":"<<sourceDone<<",\"terms_completed\":"<<completedTerms<<",\"output_a_shift\":"<<outputAShift<<",\"peak_cells\":"<<peakcells<<",\"peak_polys\":"<<peakpolys<<"}";string header=h.str();assert(header.size()<65536);ofstream o(path,ios::binary);o.write("K92SP001",8);writeLE<uint32_t>(o,header.size());o.write(header.data(),header.size());writeLE<uint32_t>(o,alive.size());
 for(auto&[id,p]:alive){writeLE<uint32_t>(o,id);o.put(char(p->role));writeLE<int32_t>(o,p->source);writeLE<int32_t>(o,p->term);writeLE<int32_t>(o,p->row);writeLE<int32_t>(o,p->mask);o.put(p->complete?1:0);writeZ(o,fmpq_numref(p->c.q),CONTENT_BITS);writeZ(o,fmpq_denref(p->c.q),CONTENT_BITS);writeLE<uint32_t>(o,p->a.size());for(auto&[m,c]:p->a){for(auto e:m)writeLE<int32_t>(o,e);writeZ(o,c->z,COEFF_BITS);}}
 o.put(cur.pending?1:0);if(cur.pending){writeLE<int32_t>(o,cur.dst);writeLE<int32_t>(o,cur.lhs);writeLE<int32_t>(o,cur.rhs);writeLE<uint64_t>(o,cur.left);writeLE<uint64_t>(o,cur.right);for(auto x:cur.key)writeLE<int64_t>(o,x);writeZ(o,cur.scale.z,PENDING_BITS);o.put(cur.valueKnown?1:0);writeZ(o,cur.value.z,PENDING_BITS);}o.flush();assert(o.good());if(o.tellp()>26980736)throw runtime_error("checkpoint_safe_RAW_bound");}
